<script setup lang="ts">
/**
 * PlayerPage (R3.9) — route container for `/app/player/:id`, the final R3 step.
 *
 * Wires the redesigned <Player> (R3.1–R3.8) to the real backend + the singleton
 * usePlayerStore:
 *  - resolves the playable URL (the deterministic direct-stream /media/:id/stream
 *    endpoint) and supplies a SYNCHRONOUS `streamUrlFor` resolver so the player's
 *    up-next auto-advance threads a fresh URL into usePlayerStore.next();
 *  - reads GET /api/v1/media/:id/playback-info for intro/outro skip markers + chapter
 *    ticks (best-effort enrichment — absent markers just disable those affordances);
 *  - builds a genre-scoped "up next" queue (usePlayerStore.setQueue) so the R3.8
 *    up-next card + autoplay actually have something to advance to;
 *  - handles `play-next` by navigating the route to the new id (URL stays correct;
 *    the id watch re-loads the title + a fresh queue);
 *  - hands playback off to the persistent <MiniPlayer> on route-leave
 *    (store.showMiniPlayer()) and reclaims it on enter/reload (store.hideMiniPlayer()),
 *    so audio/video continues across navigation and expanding the dock returns here;
 *  - paints a poster-derived ambient backdrop + loading / error / skeleton states.
 *
 * Resume restoration + the mkv/hevc transcode notice live INSIDE <Player> (R3.8);
 * this page just feeds it real data. Deep-links work and re-fetch when the id changes.
 */
import { ref, computed, inject, onMounted, watch, onBeforeUnmount } from 'vue';
import { useRoute, useRouter, onBeforeRouteLeave } from 'vue-router';
import type { MediaItem } from '../types/media-item';
import { ApiClient, ApiError } from '../api/client';
import { useMediaApiBase, useMediaDirectBase } from '../composables/useApiBase';
import { useImageSrc } from '../composables/useImageSrc';
import { buildMediaUrl } from '../api/media-query';
import { usePlayerStore } from '../stores/usePlayerStore';
import { useUserItemDataStore } from '../stores/useUserItemDataStore';
import { usePlayerUiStore } from '../stores/usePlayerUiStore';
import { playbackBlockingMessage } from './playerErrors';
import type { PhlixAppConfig } from '../app/types';
import Player from '../components/Player.vue';
import type { Chapter } from '../components/player/Scrubber.vue';
import { parsePlaybackAudioTracks, type PlaybackAudioTrack, type TimeMarker } from '../components/player/playback';
import { parseSubtitleTracks, type SubtitleTrack } from '../components/player/transcode';
import { hasSeasonRows } from '../components/series-grouping';
import { orderEpisodesForPlayback, previousEpisode, nextEpisode } from '../components/player/episode-order';
import EmptyState from '../components/ui/EmptyState.vue';
import Button from '../components/ui/Button.vue';
import Skeleton from '../components/ui/Skeleton.vue';
import Modal from '../components/ui/Modal.vue';
import { usePageTitle } from '../composables/usePageTitle';
// Stale-while-revalidate item cache (UI-2.1, U-N2) — the SAME module-level singleton the
// MediaDetailPage uses, so a browse→detail→player→back round trip reuses one cached item
// within the 60s TTL instead of re-fetching /media/:id on every visit.
import {
  getMediaItemCacheEntry,
  isMediaItemCacheFresh,
  cacheMediaItem,
} from '../composables/useMediaItemCache';

interface MediaListResponse {
  items: MediaItem[];
  total: number;
}

/**
 * Per-session cache of the ordered (playback) episode list for a whole series,
 * keyed by the resolved series-root id. Binge navigation (Next, Next, Next…)
 * walks the same series, so once it's fetched + ordered we reuse it and just
 * recompute prev/next from the current id — no parent-hop walk, no root-children
 * fetch, no N season-children fetches per episode click. Module-level so it
 * survives the page's own remount on each player→player route change; lifetime =
 * the SPA session (a small Map, one entry per series watched — bounded by how
 * many distinct series the user opens in a session). */
const seriesEpisodeCache = new Map<string, MediaItem[]>();

/** Server playback-info contract (GET /api/v1/media/:id/playback-info): intro/outro
 *  skip markers + chapter ticks. Times are in seconds. There is NO stream url —
 *  playback uses the deterministic /media/:id/stream endpoint (streamUrlFor). */
interface ServerMarker {
  start_seconds: number;
  end_seconds: number;
}
interface PlaybackInfo {
  intro_marker: ServerMarker | null;
  outro_marker: ServerMarker | null;
  chapters: { start_seconds: number; end_seconds?: number; title?: string | null }[];
  /** The source's audio streams — drives the direct-play audio menu (parsed
   *  leniently via parsePlaybackAudioTracks; absent on older servers). */
  audio_tracks?: unknown;
  /** Embedded text subtitles with SIGNED WebVTT urls usable directly in a
   *  `<track>` — drives direct-play captions (absent on older servers). */
  subtitle_tracks?: unknown;
}

// On the hub this is the relay-proxy base for the selected server, so the
// player's metadata/playback-info fetches hit that paired server inline; on the
// media server it is the app's own base. It is ALSO the byte-stream fallback:
// `streamUrlFor()` uses `directBase || apiBase`, and since S247 the relay
// genuinely serves `/media/{id}/stream` (anchored, Range/206 carried), so a
// server with no reachable public origin direct-plays over the tunnel.
const apiBase = useMediaApiBase();
/** S241: image URLs in the media payload are ROOT-RELATIVE server paths; resolve
 *  them against the same (possibly relay-proxied) base the payload came from. */
const { imgSrc } = useImageSrc();
// The paired server's own public origin on the hub (else ''). The player PREFERS
// to stream media bytes from here directly (native Range) so neither the bytes
// nor their egress cost traverse the hub; when the server advertised no reachable
// URL this is '' and `streamUrlFor()` falls back to the relay, which since S247
// routes the byte stream and carries Range/206. Transcode/HLS always go over
// `apiBase` (the proxy).
const directBase = useMediaDirectBase();
const route = useRoute();
const router = useRouter();
// W4: the configured error-catalog locale (config-time, like `messages`).
const config = inject<PhlixAppConfig | null>('phlixConfig', null);
const player = usePlayerStore();
// Per-user favorite/love state (Feature 16). The by-id fetch below resolves the
// MediaDetail — the AUTHORITATIVE source of `user_data` — so the page seeds the
// store from it as soon as the item loads. <Player> also hydrates from
// `props.media` on mount/media-change, but `hydrate` is idempotent (it `set()`s
// the entry keyed by id from the item's `user_data`), so the page seeding the
// SAME item is the source of truth and the Player's redundant re-hydrate is a
// harmless no-op. This guarantees the favorite + Love controls pre-fill from the
// server the moment the player opens.
const userItemData = useUserItemDataStore();
// S34: the shared channel that surfaces the player's theater state to the app
// shell (PhlixApp reads it to gate the chrome-removing `shell--flush`). The
// `@theater` toggle below is the single source of truth; we just mirror it here.
const playerUi = usePlayerUiStore();

const item = ref<MediaItem | null>(null);
const streamUrl = ref('');
const chapters = ref<Chapter[]>([]);
const introMarker = ref<TimeMarker | null>(null);
const outroMarker = ref<TimeMarker | null>(null);
/** Playback-info audio_tracks / subtitle_tracks — the Player's direct-play audio
 *  menu + captions sources (empty when the server doesn't send them). */
const playbackAudioTracks = ref<PlaybackAudioTrack[]>([]);
const playbackSubtitleTracks = ref<SubtitleTrack[]>([]);
const loading = ref(true);
const error = ref<string | null>(null);
const theater = ref(false);
/** P5-S5: AccessScheduled (403) or StreamLimitExceeded (429) — shown in a modal, not the error state. */
const blockingError = ref<string | null>(null);
const blockingErrorVisible = ref(false);
/** Prev/Next episode in the whole-series order (U2) — null for movies or at the
 *  ends of the series. Drives the Player's prev/next-episode buttons. */
const prevEp = ref<MediaItem | null>(null);
const nextEp = ref<MediaItem | null>(null);

const currentId = computed(() => String(route.params.id ?? ''));

// The playing item's title becomes the page title once it loads (and updates on
// up-next advance, since the id watch reloads `item`); until then the route
// default stands.
usePageTitle(() => item.value?.name);

/** Poster-derived ambient backdrop. The url() value is escaped (backslash/quote
 *  escaped, CR/LF stripped) like Scrubber.previewThumbCss so a poster URL containing
 *  `)`/`"` can't break out of the declaration (the R3.2-hardened CSS pattern). */
const ambientStyle = computed(() => {
  const url = imgSrc(item.value?.poster_url);
  if (!url) return undefined;
  const safe = url.replace(/[\\"]/g, '\\$&').replace(/[\r\n]/g, '');
  return { backgroundImage: `url("${safe}")` };
});

let controller: AbortController | null = null;
let disposed = false;

/**
 * Monotonic id of the newest `load()` run (S172).
 *
 * `load()` does NOT await `applyItem()`, and `applyItem` itself awaits
 * (`loadEpisodeNeighbours`) before it fires the genre fallback — so a whole second
 * `load()` can complete inside that await. The staleness token therefore has to belong to
 * the RUN, captured once when the run starts and carried down (see {@link LoadRun}), not
 * re-read from module scope by each writer: `loadQueue` used to read `controller` at CALL
 * time, which for a resuming superseded run is already the NEW run's controller, so
 * `myController !== controller` compared the new controller with itself and could never
 * trip. Item A's genre rows then landed in item B's up-next queue.
 *
 * Why a counter and not just the controller identity: `load()` sets `controller = null`
 * where `AbortController` is undefined (see below), and in that configuration every
 * `myController !== controller` test degrades to `null !== null` — false — so no run is
 * ever considered superseded AND no request is ever aborted. An integer is immune to that.
 */
let generation = 0;

/**
 * The identity of ONE `load()` run: its generation and its abort controller.
 *
 * Both must travel together. The generation decides whether a write may still commit; the
 * controller is the signal the run's own requests were issued with, so a superseded run
 * keeps cancelling ITS OWN fetches rather than picking up whatever controller happens to
 * be current when it resumes.
 */
interface LoadRun {
  readonly generation: number;
  readonly controller: AbortController | null;
}

/** Whether `run` has been superseded by a newer `load()` — or the page is gone. */
function isStale(run: LoadRun): boolean {
  return disposed || run.generation !== generation;
}

function isAbort(e: unknown): boolean {
  return typeof e === 'object' && e !== null && (e as { name?: string }).name === 'AbortError';
}

/** Direct-stream URL for any media id — synchronous, so the player's up-next advance
 *  (which can't await playback-info) always threads a fresh URL via player.next().
 *
 *  Prefers the server-minted **signed** `stream_url` (`/media/:id/stream?exp&sig`)
 *  when present: `/media/:id/stream` is no longer world-readable and a `<video src>`
 *  can't attach a Bearer header, so a bare path would 401 for SPA sessions (which
 *  hold a localStorage token, not a cookie). Only the single-item detail shape
 *  carries `stream_url`; queue/up-next rows (from the list endpoint) fall back to
 *  the bare path, which is fine because advancing navigates the route and re-fetches
 *  the detail (and thus a fresh signed URL) before that item actually plays. The
 *  signed path is root-relative, so prefix a base for cross-origin hosts.
 *
 *  On the hub the signed path is prefixed with the paired server's OWN public
 *  origin (`directBase`) so the `<video>` streams the bytes straight from the
 *  server with native Range. The signature authenticates the request cross-origin
 *  (no cookie needed). On the media server `directBase` is '' so this is unchanged
 *  (the page origin serves the bytes).
 *
 *  ## The fallback is the relay, and since S247 it WORKS
 *
 *  If the server reported no reachable origin, `directBase` is '' and the `||`
 *  falls through to `apiBase` — the relay-proxy base
 *  (`{hub}/api/v1/servers/{id}/proxy`). That was always what this line did; the
 *  docblock used to claim the opposite ("the relay proxy does not route
 *  /media/:id/stream"), which was wrong about the hub and made the real
 *  behaviour invisible. S247 made it correct AND deliberate: the hub admits
 *  `/media/{id}/stream` as an anchored pattern, forwards `Range` verbatim,
 *  returns the server's `206` + `Content-Range` untouched, and answers a HEAD
 *  probe with the real `Content-Length` and no body — so a server with no
 *  reachable public URL can direct-play, seek included.
 *
 *  ⚠ DIRECT-FIRST IS LOAD-BEARING. Relaying moves every byte onto the hub, so
 *  the ordering of this `||` is a bandwidth decision, not a style choice: when a
 *  reachable origin exists it must be used. Pinned by
 *  `PlayerPage.test.ts` ("prefers the direct base…" / "falls back to the relay
 *  base…"), so flipping the operands reddens a named test.
 *
 *  An unreachable-but-advertised origin still surfaces as a `<video>` error that
 *  flips the player to an HLS transcode over the proxy (see
 *  Player.onVideoError). */
function streamUrlFor(m: MediaItem): string {
  const base = directBase.value || apiBase.value;
  if (m.stream_url) {
    return /^https?:\/\//.test(m.stream_url) ? m.stream_url : `${base}${m.stream_url}`;
  }
  return `${base}/media/${encodeURIComponent(m.id)}/stream`;
}

/** Map a server marker ({start_seconds,end_seconds}) to a client TimeMarker, or null. */
function toMarker(m: ServerMarker | null | undefined): TimeMarker | null {
  return m ? { start: m.start_seconds, end: m.end_seconds } : null;
}

/** The ONE definition of "this item is an episode", shared by `applyItem` (which decides
 *  whether to await the authoritative episode-ordered path) and `loadEpisodeNeighbours`
 *  (which decides whether to resolve neighbours at all). These two MUST agree: if
 *  `applyItem` used a narrower test it would skip the episode path for an item
 *  `loadEpisodeNeighbours` would happily have handled, and — since S12 removed the
 *  duplicate cache lookup from `loadQueue` — such an item would silently fall through to
 *  the genre-similar queue instead of the next episode.
 *
 *  `episode_number` alone is NOT sufficient: the server shapes it from `metadata.episode`
 *  and emits null whenever the scanner/provider parsed no episode number
 *  (phlix-server `MediaItemShaper.php:279`), while `type` comes from the DB enum
 *  independently. `series-grouping.episodesOf()` uses this same union, so such rows DO
 *  appear in the ordered playback list. */
function isEpisodeItem(m: MediaItem): boolean {
  return m.type === 'episode' || (m.episode_number ?? null) !== null;
}

/** Genre-similar "up next" fallback queue for MOVIES — and for an episode ONLY when
 *  the awaited episode-ordered path (loadEpisodeNeighbours, run first in applyItem)
 *  resolved NO next neighbour (last episode / cache miss / failed series-tree fetch).
 *  The episode-ordered queue is the authoritative writer; this runs afterwards/otherwise
 *  so the two never race. Non-fatal: a missing queue just disables up-next.
 *
 *  `run` is the identity of the `applyItem` run that asked for this queue — NOT whatever
 *  is current when this function is entered (S172). Reading the controller at call time
 *  was the bug: a superseded run resuming from `await loadEpisodeNeighbours` picked up the
 *  NEW run's controller and so compared it with itself, never tripping, and wrote the old
 *  item's rows into the new item's queue. */
async function loadQueue(client: ApiClient, base: MediaItem, run: LoadRun): Promise<void> {
  const stale = () => isStale(run);

  // Genre-scoped fallback queue (movies, or an episode with no resolved next neighbour).
  const genre = base.genres?.[0];
  if (!genre) {
    player.setQueue([]);
    return;
  }
  try {
    const url = buildMediaUrl(apiBase.value, { genres: [genre], limit: 13, sort: 'rating', order: 'desc' });
    const res = await client.get<MediaListResponse>(url, undefined, run.controller?.signal);
    if (stale()) return;
    player.setQueue((res.items ?? []).filter((m) => m.id !== base.id).slice(0, 12));
  } catch (e) {
    if (stale() || isAbort(e)) return;
    player.setQueue([]); // a missing up-next list is non-fatal
  }
}

/** Fetch a parent's direct children (seasons/episodes), high limit so a full
 *  series arrives in one page — mirrors MediaDetailPage.fetchChildren. */
async function fetchChildren(client: ApiClient, parentId: string, signal?: AbortSignal): Promise<MediaItem[]> {
  const url = buildMediaUrl(apiBase.value, { parentId, limit: 100, sort: 'name', order: 'asc' });
  const res = await client.get<MediaListResponse>(url, undefined, signal);
  return res.items ?? [];
}

/** Walk parent_id up from an episode to its series root (episode → season →
 *  series). Best-effort: returns the highest ancestor reached (or the item
 *  itself) so a partial chain still yields a usable grouping root. Bounded to a
 *  few hops to avoid a pathological cycle. */
async function resolveSeriesRoot(client: ApiClient, item: MediaItem, signal?: AbortSignal): Promise<MediaItem> {
  let node = item;
  for (let hops = 0; hops < 4 && node.parent_id; hops += 1) {
    const res = await client.get<{ item: MediaItem }>(
      `/api/v1/media/${encodeURIComponent(node.parent_id)}`,
      undefined,
      signal,
    );
    const parent = res.item;
    if (!parent) break;
    node = parent;
    if (parent.type === 'series') break;
  }
  return node;
}

/** Set the prev/next refs AND seed the up-next queue from an already-ordered
 *  whole-series playback list. Seeding the queue HERE (rather than in a separate,
 *  racing writer) makes the episode-ordered list the single authoritative source
 *  for both the fresh-fetch and the binge cache-hit paths; the genre fallback in
 *  loadQueue only runs when this resolves NO next episode. */
function applyNeighbours(ordered: MediaItem[], currentEpId: string): void {
  prevEp.value = previousEpisode(ordered, currentEpId);
  nextEp.value = nextEpisode(ordered, currentEpId);
  // UI-0.7: the up-next queue is the remaining episodes AFTER the current one, in
  // playback order. When empty (last episode) we leave the queue untouched so the
  // genre fallback that applyItem fires can populate it.
  const idx = ordered.findIndex((e) => e.id === currentEpId);
  const remaining = idx >= 0 ? ordered.slice(idx + 1) : [];
  if (remaining.length) player.setQueue(remaining);
}

/** Find a cached ordered playback list that already contains `episodeId`, or
 *  null. Binge nav stays within one series, so the next sibling is almost always
 *  in a list we fetched a click ago — a cache hit skips ALL series-tree fetches. */
function cachedOrderedFor(episodeId: string): MediaItem[] | null {
  for (const ordered of seriesEpisodeCache.values()) {
    if (ordered.some((e) => e.id === episodeId)) return ordered;
  }
  return null;
}

/** Build the whole-series ordered episode list and resolve the prev/next
 *  neighbours of the currently-playing episode (U2). Non-fatal: any failure just
 *  leaves the buttons hidden. Only runs for episode content; movies clear them.
 *  Caches the ordered list per series-root id so repeated (binge) navigation
 *  within the same series reuses it and skips the parent-hop walk + children
 *  fetches entirely (Finding 1). Uses the PLAYBACK ordering (numbered seasons
 *  only; Specials excluded from the auto-advance chain — Finding 2). */
async function loadEpisodeNeighbours(client: ApiClient, base: MediaItem, run: LoadRun): Promise<void> {
  prevEp.value = null;
  nextEp.value = null;
  if (!isEpisodeItem(base)) return;
  // Cache hit: this episode is already in a fetched series order — just recompute
  // prev/next, no fetches.
  const cached = cachedOrderedFor(base.id);
  if (cached) {
    applyNeighbours(cached, base.id);
    return;
  }
  // S172: the run's own token, not the current one — see loadQueue.
  const stale = () => isStale(run);
  try {
    const root = await resolveSeriesRoot(client, base, run.controller?.signal);
    if (stale()) return;
    let children = await fetchChildren(client, root.id, run.controller?.signal);
    if (stale()) return;
    // Flatten season-container rows to their episodes (uniform season grouping).
    if (hasSeasonRows(children)) {
      const seasonRows = children.filter((c) => c.type === 'season');
      const lists = await Promise.all(
        seasonRows.map((s) => fetchChildren(client, s.id, run.controller?.signal).catch(() => [] as MediaItem[])),
      );
      if (stale()) return;
      children = [...children.filter((c) => c.type !== 'season'), ...lists.flat()];
    }
    const ordered = orderEpisodesForPlayback(children);
    if (ordered.length) seriesEpisodeCache.set(root.id, ordered);
    // Sets prev/next AND seeds the authoritative episode-ordered up-next queue.
    applyNeighbours(ordered, base.id);
  } catch (e) {
    if (stale() || isAbort(e)) return;
    prevEp.value = null;
    nextEp.value = null;
  }
}

async function load(): Promise<void> {
  const id = currentId.value;
  controller?.abort();
  controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
  // S172: claim a new generation and carry THIS run's identity into every async writer, so
  // a run that is superseded while awaiting cannot commit an item, its neighbours or its
  // up-next queue over the newer item's.
  generation += 1;
  const run: LoadRun = { generation, controller };
  loading.value = true;
  error.value = null;
  chapters.value = [];
  introMarker.value = null;
  outroMarker.value = null;
  playbackAudioTracks.value = [];
  playbackSubtitleTracks.value = [];
  prevEp.value = null;
  nextEp.value = null;
  player.hideMiniPlayer(); // the full player owns playback while we're on this route
  if (!id) {
    error.value = 'No media id provided';
    loading.value = false;
    return;
  }
  const client = new ApiClient({ baseUrl: apiBase.value });
  // Fire item + playback-info concurrently — BOTH requests are dispatched before we
  // await either, so total marker latency is max(item, playback-info) rather than the
  // sum of two serial round trips. The item is critical (errors propagate) and gates
  // `loading`; playback-info is best-effort — markers/tracks populate reactively via the
  // .then below when it resolves, and the Player watch at Player.vue:692-698 handles late
  // serverSubtitleTracks the same way. Errors degrade to empty markers (no skip buttons,
  // no chapter ticks).
  client
    .get<PlaybackInfo>(`/api/v1/media/${encodeURIComponent(id)}/playback-info`, undefined, run.controller?.signal)
    .then((info) => {
      // S172: a superseded run's markers/chapters/tracks belong to the item the user left,
      // and this `.then` outlives its run exactly like the queue writers do.
      if (isStale(run)) return;
      chapters.value = (info?.chapters ?? []).map((c) => ({ start: c.start_seconds, end: c.end_seconds, title: c.title ?? undefined }));
      introMarker.value = toMarker(info?.intro_marker);
      outroMarker.value = toMarker(info?.outro_marker);
      playbackAudioTracks.value = parsePlaybackAudioTracks(info?.audio_tracks);
      playbackSubtitleTracks.value = parseSubtitleTracks(info?.subtitle_tracks);
    })
    .catch(() => null);

  // UI-2.1 stale-while-revalidate item cache (shared singleton with MediaDetailPage).
  // A fresh cached item mounts the player instantly with NO by-id round trip; playback-info
  // is STILL fetched fresh above (best-effort markers). A stale/absent entry falls through
  // to the fetch below and, on failure, is served as a fallback.
  const cached = getMediaItemCacheEntry(id);
  const now = Date.now();
  if (cached && isMediaItemCacheFresh(cached, now)) {
    applyItem(client, cached.item, run);
    return;
  }

  // Loading clears after the item resolves so the player mounts as soon as possible,
  // without waiting for playback-info (which may be slow/missing).
  let mediaItem: MediaItem | null = null;
  try {
    const itemResponse = await client.get<{ item: MediaItem }>(
      `/api/v1/media/${encodeURIComponent(id)}`,
      undefined,
      run.controller?.signal,
    );
    mediaItem = itemResponse.item;
  } catch (e) {
    // S172: `isStale` rather than `disposed` — a newer load() has already taken over the
    // page, so neither this run's error state nor its SWR fallback may be applied.
    if (isStale(run) || isAbort(e)) return;
    if (e instanceof ApiError && (e.status === 403 || e.status === 429)) {
      // W4 (error-code doctrine): prefer the machine `code` the W2 server wave
      // adds and localize it through the contracts catalog; until then the
      // legacy `error` pseudo-code texts still match (see ./playerErrors.ts).
      const blockingMessage = playbackBlockingMessage(e.body, config?.locale);
      if (blockingMessage !== null) {
        // A hard access block must NOT be masked by a stale cache — surface it.
        blockingError.value = blockingMessage;
        blockingErrorVisible.value = true;
        loading.value = false;
        return;
      }
    }
    // SWR fallback: a transient refresh failure (network blip / 5xx) still lets a
    // previously-cached title play. Mirrors MediaDetailPage's stale-on-failure behavior.
    if (cached) {
      applyItem(client, cached.item, run);
      return;
    }
    error.value = e instanceof Error ? e.message : 'Failed to load media';
    loading.value = false;
    return;
  }
  if (isStale(run)) return;
  // Guard: if mediaItem is falsy despite a resolved promise, treat as a load failure
  // rather than propagating undefined into streamUrlFor (Fail Fast). A stale cache, if
  // present, still beats erroring out.
  if (!mediaItem) {
    if (cached) {
      applyItem(client, cached.item, run);
      return;
    }
    error.value = 'Failed to load media item';
    loading.value = false;
    return;
  }
  // Refresh the shared cache for the next visit (browse→detail→player→back reuse).
  cacheMediaItem(id, mediaItem, now);
  applyItem(client, mediaItem, run);
}

/**
 * Mount the player from a resolved (freshly-fetched OR cached) item: seed the per-user
 * favorite/love controls from the server `user_data` (Feature 16; <Player> also hydrates
 * on mount but `hydrate` is idempotent), resolve the deterministic direct-stream URL
 * up front (synchronous, so up-next auto-advance can reuse the resolver), clear loading,
 * and kick off the best-effort up-next queue.
 *
 * Up-next is populated by a SINGLE writer to kill the previous two-racer bug (S12): an
 * unawaited genre queue and an unawaited episode-neighbour lookup both wrote the queue,
 * so a slow genre fetch could resolve LAST and clobber the authoritative episode order.
 * Now, for an episode we AWAIT loadEpisodeNeighbours FIRST; when it resolves a next
 * episode it has already seeded the episode-ordered queue (via applyNeighbours), so we
 * RETURN EARLY and never fire the genre queue. Only a non-episode — or an episode with no
 * next neighbour (last episode / cache miss / failed series-tree fetch) — falls through
 * to the genre-similar fallback queue. This also guarantees player.upNext is populated
 * before auto-play checks it when onEnded() fires (Issue 8).
 *
 * `run` is the identity of the `load()` that produced `mediaItem`. This function is NOT
 * awaited by its caller, and it awaits internally, so `run` is what keeps a superseded run
 * from committing (S172).
 *
 * There is deliberately NO staleness check on ENTRY, because `run` is current at every
 * call site and a check here could therefore never fire — an unfalsifiable guard, which
 * this repo treats as a defect in its own right. The four call sites, all in `load()`:
 * the fresh-cache fast path runs in the same synchronous turn as `generation += 1` (the
 * first `await` in `load()` comes after it), and the other three are each preceded by an
 * `isStale(run)` return with no `await` in between. Add a call site behind a new `await`
 * and that invariant breaks — guard it there, or restore the entry check.
 *
 * The check that IS needed is after `await loadEpisodeNeighbours`, because a whole newer
 * `load()` can start AND finish inside that await. It is what stops the genre fallback:
 * the fetch it fires would otherwise be issued under the new run's controller and its rows
 * written over the new item's up-next queue.
 */
async function applyItem(client: ApiClient, mediaItem: MediaItem, run: LoadRun): Promise<void> {
  item.value = mediaItem;
  userItemData.hydrate(mediaItem);
  streamUrl.value = streamUrlFor(mediaItem);
  loading.value = false;

  // Episode: resolve the authoritative episode-ordered neighbours + queue FIRST, and
  // when a next episode exists RETURN EARLY. loadEpisodeNeighbours has already seeded the
  // episode-ordered queue, so the genre queue must NOT run — that removes the race.
  // The predicate is shared with loadEpisodeNeighbours (isEpisodeItem) — see the note
  // there: a narrower test here would strand `type:'episode'` rows that carry no parsed
  // episode_number on the genre queue.
  if (isEpisodeItem(mediaItem)) {
    await loadEpisodeNeighbours(client, mediaItem, run);
    // A newer load() may have completed entirely inside that await. `nextEp` then belongs
    // to the NEW item, so neither the early return nor the fallback below may be decided
    // from it — this run is finished (S172).
    if (isStale(run)) return;
    if (nextEp.value) return;
  }

  // Non-episode, or an episode with no next neighbour (last episode / cache miss / failed
  // series-tree fetch): genre-similar fallback queue (background, non-fatal).
  void loadQueue(client, mediaItem, run);
}

onMounted(load);
watch(currentId, load);

// Hand playback off to the persistent mini-player when navigating AWAY from the player
// route (param changes between player items fire onBeforeRouteUpdate, NOT leave, so a
// binge-advance keeps the full player). Only when there's a live session to continue.
onBeforeRouteLeave(() => {
  if (player.current && player.streamUrl) player.showMiniPlayer();
});

onBeforeUnmount(() => {
  disposed = true;
  controller?.abort();
  controller = null;
  // Leaving the player route (this page unmounts) clears the shared theater state
  // so a later non-theater visit can't inherit a stale `true` and flush the shell.
  // Binge/up-next navigation reuses this component instance (param change, not a
  // remount), so theater persists across auto-advance — only a true route-leave resets.
  playerUi.reset();
});

function onBack(): void {
  router?.back();
}
/** Player advanced the queue (up-next countdown or "Play now"); the store is already
 *  on the new item — sync the route so the URL + :id match (the id watch re-loads). */
function onPlayNext(next: MediaItem): void {
  router?.push({ name: 'player', params: { id: next.id } }).catch(() => {});
}
/** Prev/Next episode button (U2) — navigate to the adjacent episode's player
 *  route; the id watch re-loads the item, queue, and neighbours. */
function onPlayEpisode(ep: MediaItem): void {
  router?.push({ name: 'player', params: { id: ep.id } }).catch(() => {});
}
function onTheater(active: boolean): void {
  theater.value = active;
  // Surface the SAME toggle state to the shell so PhlixApp removes the chrome
  // (`shell--flush`) in lock-step with this page's 100dvh stage growth.
  playerUi.setTheaterActive(active);
}
/** P5-S5: dismiss the blocking-error modal and return to browse. */
function onBlockingErrorOk(): void {
  blockingErrorVisible.value = false;
  onBack();
}
</script>

<template>
  <div class="player-page" :class="{ 'is-theater': theater }">
    <div
      v-if="ambientStyle && !loading && !error"
      class="player-page__ambient"
      :style="ambientStyle"
      aria-hidden="true"
    />

    <div class="player-page__stage">
      <div
