        :description="error"
      >
        <template #actions>
          <Button variant="solid" @click="load">Retry</Button>
          <Button variant="ghost" @click="onBack">Back</Button>
        </template>
      </EmptyState>

      <Player
        v-else-if="item"
        :media="item"
        :stream-url="streamUrl"
        :stream-url-for="streamUrlFor"
        :api-base="apiBase"
        :chapters="chapters"
        :intro-marker="introMarker"
        :outro-marker="outroMarker"
        :playback-audio-tracks="playbackAudioTracks"
        :playback-subtitle-tracks="playbackSubtitleTracks"
        :prev-episode="prevEp"
        :next-episode="nextEp"
        :autoplay="true"
        @back="onBack"
        @play-next="onPlayNext"
        @play-episode="onPlayEpisode"
        @theater="onTheater"
      />
    </div>

    <!-- P5-S5: AccessScheduled / StreamLimitExceeded blocking-error modal -->
    <Modal v-model="blockingErrorVisible" title="Cannot Play" size="sm" :dismissible="false" hide-close>
      <p class="player-page__blocking-error">{{ blockingError }}</p>
      <template #footer>
        <Button variant="solid" @click="onBlockingErrorOk">OK</Button>
      </template>
    </Modal>
  </div>
</template>

